async function takeSnapshot(){
 if(state.phase!=='running')return;
 const svg=$('frontSvg').cloneNode(true);svg.setAttribute('xmlns','http://www.w3.org/2000/svg');svg.setAttribute('width','1000');svg.setAttribute('height','580');
 const svgText=new XMLSerializer().serializeToString(svg);
 let objectUrl=null;
 try{
  objectUrl=URL.createObjectURL(new Blob([svgText],{type:'image/svg+xml;charset=utf-8'}));
  const picture=new Image();picture.decoding='async';
  await new Promise((resolve,reject)=>{picture.onload=resolve;picture.onerror=()=>reject(new Error('SVG non leggibile'));picture.src=objectUrl;});
  const canvas=document.createElement('canvas');canvas.width=850;canvas.height=493;
  const ctx=canvas.getContext('2d');if(!ctx)throw Error('Canvas non disponibile');ctx.drawImage(picture,0,0,850,493);
  const data=canvas.toDataURL('image/webp',.87);if(!data.startsWith('data:image/'))throw Error('Formato immagine non supportato');
  const snap={id:state.nextId++,day:state.day,view:'front',image:data,caption:'Istantanea della vista frontale osservata realmente al giorno '+state.day};
  state.snapshots.unshift(snap);
  note('Istantanea della vista frontale acquisita e salvata volontariamente.', 'action');
  renderAndSave();notice('Istantanea del giorno '+state.day+' registrata nel diario.');
 }catch(e){issue('Non è stato possibile acquisire l’immagine in questo browser. Se stai usando i sorgenti separati, prova la versione HTML autonoma. Nessuna istantanea è stata registrata.');}
 finally{if(objectUrl)URL.revokeObjectURL(objectUrl);}
}
function photoGallery(){const snaps=Array.isArray(state.snapshots)?state.snapshots:[];
 const cards=snaps.length?snaps.map(s=>`<figure class="snapshot"><img src="${safeText(s.image.startsWith('data:image/')?s.image:'')}" alt="Istantanea osservata della vista frontale al giorno ${s.day}"><figcaption>${safeText(s.caption)} · Giorno ${s.day}</figcaption></figure>`).join(''):'<p>Nessuna istantanea registrata. Durante l’osservazione scegli «Salva un’istantanea»: sarà associata al giorno effettivamente visibile.</p>';
 openModal('Istantanee osservate',`<p>Queste immagini provengono soltanto da osservazioni volontarie; non ricostruiamo i giorni saltati.</p><div class="snapshot-gallery">${cards}</div>`);
}

function scientificModal(){openModal('Registro di verifica scientifica',`<p class="notice">MODELLO ECOLOGICO ESPLORATIVO · RISULTATI NON MISURATI NELLA VASCA</p><p><b>v0.25:</b> il ciclo N include adesso anche biofilm su superfici iniziali, pascolo locale degli invertebrati, alimento introdotto contabilizzato e ritorno del detrito. Resta in funzione il percorso: foglia → detrito organico → azoto minerale aggregato → azoto incorporato nelle piante. Le quantità iniziali non dichiarate sono proxy, e i parametri di conversione/assorbimento sono convenzioni esplicite. Non equivale a una misura di NH₄, NO₂, NO₃, ossigeno, crescita botanica reale o biomassa microbica.</p><p>Il laboratorio include studi distinti sulla lisciviazione iniziale di Alnus glutinosa e Quercus ilex (non Quercus robur), dati misurati di azoto totale di Quercus serrata, una mappa documentale della provenienza potenziale dei microrganismi (non certifica presenza reale; il biofilm di gioco è un proxy contabile separato), un tracciante conservativo teorico per l’evaporazione, una tabella USGS di riferimento dell’ossigeno a saturazione (non una misura della vasca), un calcolatore stechiometrico della nitrificazione (EPA 2008) e una ricostruzione quantitativa del protocollo di Oertli 1991 con massa iniziale documentata di 4,85 g; nessuno di questi esperimenti è automaticamente applicato alle foglie collocate tramite catalogo. Nessuno dei due quantifica azoto o durezza nella vasca. Rimane un confronto numerico con due coefficienti misurati nella letteratura per Quercus robur in due stagni e uno scenario di evaporazione per vasca aperta derivato dalle misure su acqua dolce in contenitori da 14 L, osservati per 15 giorni; solo i salvataggi precedenti conservano il riferimento alla piscina. La v0.23 applica, soltanto come modello esplorativo e limitato ai primi 32 giorni bagnati, i coefficienti di perdita di massa di Abril et al. (2021) alle foglie identificate. Non è una cinetica calibrata per la vasca domestica senza filtro; i rapporti EPA sono solo rapporti chimici teorici, non tassi di nitrificazione. Il codice non inventa concentrazioni, mortalità, riproduzione, colonizzazioni o tempi di maturazione; le velocità delle foglie provengono da uno studio in torrente e sono etichettate come modello esplorativo.</p><ul><li><strong>Implementato:</strong> bilancio formale dell’azoto tra foglie, detrito, nutrienti, piante, biofilm, alimento e animali, con verifiche di conservazione e registro di provenienza di materiali visibili (con identificazione botanica delle foglie e massa facoltativa dichiarata, mai misurata dal gioco); bilancio quantitativo conservativo dell’acqua in scenario fisico non calibrato per vasca aperta, senza stima per coperchio ventilato; confronto temporale numerico da Oertli 1991 (due stagni, non vasca); vasca asciutta, allestimento, vista frontale e zenitale, introduzioni iniziali, riempimento, chiusura all’avvio, tempo manuale +1/+3/+7, salvataggio locale, diario, istantanee volontarie e rete ecologica documentale condizionata agli elementi visibili.</li><li><strong>Verificato a livello di principio:</strong> origine non spontanea delle comunità microbiche, decomposizione dipendente dalle condizioni e dai materiali, conservazione delle sostanze disciolte durante la sola evaporazione.</li><li><strong>Non ancora calibrato o implementato:</strong> cinetiche di decomposizione calibrate per questa vasca e nitrificazione, scambi gassosi quantitativi, evaporazione predittiva specifica dell’acquario e della copertura, crescita reale, cicli vitali, predazione, bilanci completi di carbonio e ossigeno, osservabilità strumentale, PDF del diario, microscopio e SVG anatomici scomponibili.</li><li><strong>Asset grafici:</strong> ritagli PNG delle tavole fornite; non sono ancora veri vettori animabili per parti del corpo.</li></ul><h4>Riferimenti verificabili</h4>${referenceItems.map(([a,b,c])=>`<div class="modalentry"><b>${safeText(a)}</b><p>${safeText(b)} <a href="${safeText(c)}" target="_blank" rel="noopener">Fonte ↗</a></p></div>`).join('')}<p>Per interpretare le cinetiche come misure o previsioni reali della vasca saranno necessarie identificazioni tassonomiche, dati applicabili, assunzioni dichiarate, unità fisiche, verifiche di conservazione e test riproducibili.</p>`);}
function allJournal(){openModal('Diario dell’ecosistema',`<p>Le voci registrano soltanto azioni e stati visualizzati. I giorni intermedi dei salti non sono presentati come osservazioni.</p>${state.journal.map(j=>`<div class="modalentry">${journalEntry(j)}</div>`).join('')}<button class="secondary full" type="button" id="openPhotoGallery">Vedi istantanee (${state.snapshots.length})</button>`);$('openPhotoGallery').addEventListener('click',photoGallery);}
