 window.__TEC_TEST__={getState:()=>JSON.parse(JSON.stringify(state)),step:advance,reset:()=>{state=initial();tool='sand';currentStep=1;renderAndSave()},invariants:()=>({singleTank:true,waterWithinBounds:state.waterLevel>=0&&state.waterLevel<=1,closedAfterStart:state.phase!=='running'||$('buildTools').hidden,dayIsInteger:Number.isInteger(state.day),noInventedRates:state.ecology.validatedKinetics===false,modelLiteratureBounded:window.TECLitterDynamics.SOURCE.maxWetDays===32,leafCatalogIntegrity:state.objects.filter(o=>o.kind==='leaf').every(o=>o.leafSpecies===null||Object.hasOwn(LEAF_CATALOG,o.leafSpecies)),noInventedLeafMass:state.objects.filter(o=>o.kind==='leaf').every(o=>o.hypotheticalDryMassG===null||(Number.isFinite(o.hypotheticalDryMassG)&&o.hypotheticalDryMassG>0)),snapshotsOnlyRealDays:(state.snapshots||[]).every(s=>s.day<=state.day),materialLedgerMatchesVisible:(()=>{let inputs=(state.matterLedger||[]).filter(f=>f.type==='in').length,outputs=(state.matterLedger||[]).filter(f=>f.type==='out').length;return state.matterLedgerComplete===false||inputs-outputs===state.objects.filter(o=>isCountedMatter(o.kind)).length})(),formalMassBalance:window.TECBalance.selfTest().allPassed,leafLiteratureReference:window.TECLeafReference.selfTest().allPassed,tracerConservation:window.TECTracer.selfTest().allPassed,leafElementChemistry:window.TECLeafElements.selfTest().allPassed,leafSpeciesStockReference:window.TECLeafInventory.selfTest().allPassed,leafMatterLedgerReference:window.TECLeafMatterLedger.selfTest().allPassed,leafMassProtocol:window.TECLeafMassProtocol.selfTest().allPassed,replicateObservationProtocol:window.TECReplicateObservations.selfTest().allPassed,retrievalSeriesProtocol:window.TECLeafRetrievalSeries.selfTest().allPassed,microbialProvenanceAudit:window.TECMicrobialProvenance.selfTest().allPassed,microbialEntryHistory:window.TECMicrobialEntryHistory.selfTest().allPassed,processEvidenceGates:window.TECProcessEvidenceGates.selfTest().allPassed,waterLitterInterface:window.TECWaterLitterInterface.selfTest().allPassed,waterLitterSequential:window.TECWaterLitterInterface.valid(state.exposureLedger)&&state.exposureLedger.processedThroughDay===state.day,waterLitterNoInventedFlux:window.TECWaterLitterInterface.evaluate(state).releaseToWaterMg===null,litterDynamics:window.TECLitterDynamics.selfTest().allPassed,litterNoInventedNitrogen:window.TECLitterDynamics.evaluate(state).plantAvailableNitrogenMg===null,leafHistoryReference:(()=>{const a=window.TECLeafMatterLedger.audit(state.objects,state.matterLedger,state.matterLedgerComplete);return state.matterLedgerComplete===false||(a.validHistory&&a.referenceIdentityHolds===true)})(),litterProtocol:window.TECLitterProtocol.selfTest().allPassed,earlyLeachingSpecies:window.TECEarlyLeaching.selfTest().allPassed,oxygenReference:window.TECOxygenReference.selfTest().allPassed,nitrificationStoichiometry:window.TECNitrification.selfTest().allPassed,waterBalanceEngine:window.TECWaterBudget.selfTest().allPassed,waterBudgetInvariant:!state.waterBudget||window.TECWaterBudget.valid(state.waterBudget),ecoCycleSelfTest:window.TECEcoCycleN.selfTest().allPassed,ecoCycleBalance:!state.ecoCycleN||window.TECEcoCycleN.valid(state.ecoCycleN),trophicEngine:window.TECTrophicWeb.selfTest().allPassed,oxygenEngine:window.TECOxygenCycle.selfTest().allPassed,oxygenBalance:state.phase!=='running'||window.TECOxygenCycle.valid(state.oxygenCycle),oxygenSequential:state.phase!=='running'||state.oxygenCycle.processedThroughDay===state.day,oxygenWaterMatch:state.phase!=='running'||Math.abs(state.oxygenCycle.waterL-state.waterBudget.currentL)<1e-7,trophicLedger:!state.ecoCycleN||window.TECTrophicWeb.valid(state.ecoCycleN.trophic),ecoCycleSequential:!state.ecoCycleN||state.ecoCycleN.processedThroughDay===state.day})};
 render();openStorage();root.__tecMounted=true;
